/*
# Expand Exercise Catalog — Part 3: Additional Pro+ Exercises

Adds ~150 more plus-tier exercises to reach 500+ total catalog.
Covers additional chest, back, shoulders, arms, legs, glutes, core, Olympic, plyometric, kettlebell, strongman, mobility, and accessory movements.
Uses ON CONFLICT to skip existing names.
*/

ON CONFLICT (name) DO NOTHING;

SELECT COUNT(*) as total, COUNT(*) FILTER (WHERE access_tier = 'free') as free, COUNT(*) FILTER (WHERE access_tier = 'pro') as pro, COUNT(*) FILTER (WHERE access_tier = 'plus') as plus FROM exercises;
